CREATE OR REPLACE FUNCTION public.dungeon_auto_attackers(p_run dungeon_runs, p_squad jsonb, p_foe jsonb, p_round integer)
 RETURNS TABLE(id bigint, ord integer, ready boolean, weak boolean, cp integer, hp numeric)
 LANGUAGE sql
